/**
 * Computes the output path for the TypeScript incremental compilation state
 * file (.tsbuildinfo) for a given tsconfig, following the same resolution rules
 * as `tsc`:
 * - if `tsBuildInfoFile` is set, use it as-is;
 * - if `outFile` is set, use the `outFile` location with its basename (without
 *   the `.js` extension) plus `.tsbuildinfo`;
 * - if `outDir` is set, use `{outDir}/{configBaseName}.tsbuildinfo`;
 * - otherwise, the file is emitted in place at
 *   `{projectRoot}/{configBaseName}.tsbuildinfo`.
 */
function getTsBuildInfoOutput(
  configBaseNameNoExt: string,
  tsConfig: ParsedTsconfigData,
  workspaceRoot: string,
  project: ProjectContext
): string {
  // https://www.typescriptlang.org/tsconfig#tsBuildInfoFile
  if (tsConfig.options.tsBuildInfoFile) {
    return pathToInputOrOutput(
      tsConfig.options.tsBuildInfoFile,
      workspaceRoot,
      project
    );
  }

  if (tsConfig.options.outFile) {
    const outFileName = basename(tsConfig.options.outFile, '.js');
    const outFileDir = relative(workspaceRoot, dirname(tsConfig.options.outFile));
    return pathToInputOrOutput(
      joinPathFragments(outFileDir, `${outFileName}.tsbuildinfo`),
      workspaceRoot,
      project
    );
  }

  if (tsConfig.options.outDir) {
    return pathToInputOrOutput(
      joinPathFragments(
        tsConfig.options.outDir,
        `${configBaseNameNoExt}.tsbuildinfo`
      ),
      workspaceRoot,
      project
    );
  }

  return joinPathFragments(
    '{projectRoot}',
    `${configBaseNameNoExt}.tsbuildinfo`
  );
